from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parent.parent
SITE=ROOT/'output/concept'

def esc(s): return html.escape(str(s),quote=True)
def arrow(): return '<span aria-hidden="true">↗</span>'
def btn(text,href,kind='dark'): return f'<a class="button button-{kind}" href="{href}">{text}{arrow()}</a>'
def hand(text,cls=''): return f'<p class="hand {cls}">{text}</p>'
def heart(): return '<svg class="heart" viewBox="0 0 45 43" fill="none" aria-hidden="true"><path d="M23 35C16 30 4 24 5 15C6 5 19 4 23 14C27 3 42 6 40 17C39 25 28 31 23 35Z" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"/></svg>'
def depth_seam(kind, foods):
 # Decorative silhouettes belong to the boundary, not to the content grid.
 pieces=''.join(f'<span class="depth-object depth-object-{i+1}"><img class="depth-motion" data-depth="{36 if i == 0 else -24}" data-depth-turn="{4 if i == 0 else -6}" src="assets/depth/{food}.webp" width="400" height="400" alt="" loading="lazy" decoding="async"></span>' for i,food in enumerate(foods))
 return f'<span class="depth-seam depth-seam-{kind}" aria-hidden="true">{pieces}</span>'
nav=[('catalogue.html','Продукция'),('about.html','О нас'),('partners.html','Партнёрам'),('contacts.html','Контакты')]
def header(active):
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if active==url else '')+f'>{name}</a>' for url,name in nav)
 return f'''<a class="skip-link" href="#main">Перейти к содержанию</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html" aria-label="Новоферма — главная"><img src="assets/logo-reference.webp" width="342" height="64" alt="NOVOferma"></a><nav class="desktop-nav" aria-label="Основная навигация">{links}</nav><div class="header-actions">{btn('Где купить','where-to-buy.html')}<button class="menu-toggle" aria-label="Открыть меню" aria-controls="site-menu" aria-expanded="false"><span></span><span></span></button></div></div></header><dialog id="site-menu" class="menu-dialog" aria-label="Меню сайта"><div class="menu-top"><a class="brand" href="index.html"><img src="assets/logo-reference.webp" width="342" height="64" alt="NOVOferma"></a><button class="menu-close icon-button" aria-label="Закрыть меню">×</button></div><nav aria-label="Мобильная навигация">{links}<a href="where-to-buy.html">Где купить</a></nav>{hand('Для ужина. Для кино. Для своих.')}</dialog>'''
def footer():return f'''<footer class="site-footer"><div class="wrap"><div class="footer-top"><a class="brand" href="index.html"><img src="assets/logo-reference.webp" width="342" height="64" alt="NOVOferma"></a>{hand('Для ужина. Для кино. Для своих.')}<a class="footer-mail" href="mailto:info@novoferma.ru">info@novoferma.ru {arrow()}</a></div><div class="footer-bottom"><p>© 2026 ООО «НОВОФЕРМА»</p><nav aria-label="Навигация в подвале"><a href="catalogue.html">Продукция</a><a href="partners.html">Партнёрам</a><a href="contacts.html">Контакты</a></nav><a href="tel:+78129155454">+7 (812) 915-54-54</a></div></div></footer>'''
def page(filename,title,content,active='',desc='Замороженные полуфабрикаты из курицы и индейки. Новоферма — для ужина, для кино, для своих.'):
 s=f'''<!doctype html><html lang="ru"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#fff5e3"><meta name="description" content="{esc(desc)}"><title>{esc(title)} — Новоферма</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="depth.css"><script src="script.js" defer></script><script src="depth.js" defer></script></head><body class="page-{filename.removesuffix(".html")}">{header(active)}<main id="main">{content}</main>{footer()}<button class="to-top icon-button" aria-label="Наверх">↑</button></body></html>'''
 (SITE/filename).write_text(s)

def crumb(name): return f'<nav class="breadcrumb wrap" aria-label="Хлебные крошки"><a href="index.html">Главная</a><span aria-hidden="true">/</span><span>{name}</span></nav>'
def contactband(): return f'<section class="partner-band wrap" data-depth-scene>{depth_seam("cta", ["strip"])}<div><p class="eyebrow">Для магазинов, кафе и ресторанов</p><h2>Добавим Новоферму<br>в ваш ассортимент?</h2></div><div><p>Обсудим продукцию<br>и условия сотрудничества.</p>{btn("Обсудить поставки","partners.html","cream")}</div></section>'

# Source data is replaced by the verified inventory when available.
fallback=[
 {'id':'meatballs','name':'Фрикадельки «Классические»','weight':'500 г','meat':'Из курицы','category':'Фрикадельки','image':'assets/meatballs-600.webp'},
 {'id':'nuggets','name':'Наггетсы куриные','weight':'400 г','meat':'Из курицы','category':'Наггетсы','image':'assets/pack-nuggets.webp'},
 {'id':'turkey','name':'Наггетсы с индейкой «Фитнес»','weight':'400 г','meat':'С индейкой','category':'Наггетсы','image':'assets/turkey-nuggets-600.webp'},
 {'id':'strips','name':'Стрипсы','weight':'400 г','meat':'Из курицы','category':'Стрипсы','image':'assets/pack-strips.webp'},
 {'id':'popcorn','name':'Куриный попкорн','weight':'400 г','meat':'Из курицы','category':'Попкорн','image':'assets/pack-popcorn.webp'}]
products=fallback
source=SITE/'products.json'
if source.exists():
 raw=json.loads(source.read_text())
 if isinstance(raw,dict):raw=raw.get('products',[])
 if raw:products=raw
# Stable normalisation permits a catalogue sourced by the independent inventory.
for i,p in enumerate(products):
 p['id']=p.get('id',p.get('slug',f'product-{i+1}'))
 p['name']=p.get('displayName',p.get('name',p.get('title','Продукт')))
 p['weight']=p.get('weight',p.get('mass',''))
 p['meatKey']=p.get('meat') or 'unknown'
 p['meat']=p.get('meatLabel') or ('С индейкой' if p['meatKey']=='turkey' else 'Из курицы' if p['meatKey']=='chicken' else 'Из мяса птицы')
 p['category']=p.get('categoryLabel',p.get('category','Наггетсы' if 'наггетс' in p['name'].lower() else 'Фрикадельки' if 'фрикадель' in p['name'].lower() else 'Попкорн' if 'попкорн' in p['name'].lower() else 'Стрипсы' if 'стрипс' in p['name'].lower() else 'Котлеты и биточки'))
 p['image']=p.get('image',p.get('local_image','assets/meatballs-600.webp'))
 if 'assets/' not in p['image']:p['image']='assets/catalogue/'+p['image'].split('/')[-1]
 # The reference PDF supplies the exact packaging art for these three products.
 low=p['name'].lower()
 if low in ['наггетсы куриные','куриные наггетсы']:p['image']='assets/pack-nuggets.webp'
 if 'попкорн' in low:p['image']='assets/pack-popcorn.webp'
 if 'стрипс' in low:p['image']='assets/pack-strips.webp'
 cutout=SITE/'assets/catalogue-cutout'/f"{p['id']}.webp"
 if cutout.exists():p['image']='assets/catalogue-cutout/'+p['id']+'.webp'
 p['url']='product-'+p['id']+'.html'

def find(part):return next((p for p in products if part in p['name'].lower()),products[0])
def card(p,n=1):
 turkey=p.get('meatKey','turkey' if 'индейк' in p['meat'].lower() else 'chicken')
 return f'''<article class="product-card reveal" data-meat="{turkey}" data-category="{esc(p['category'])}" data-name="{esc(p['name'].lower())}"><a class="product-image" data-tilt href="{p['url']}" aria-label="{esc(p['name'])}"><img class="tilt-plane" src="{p['image']}" width="600" height="500" loading="lazy" alt="{esc(p['name'])}"></a><div class="product-meta"><span>{n:02d}</span><span>{p['meat']} · {p['weight']}</span></div><a class="product-title" href="{p['url']}"><h3>{p['name']}</h3><span class="circle-arrow" aria-hidden="true">↗</span></a><p class="product-caption">{'Знакомый вкус. Любимый соус.' if 'наггетс' in p['name'].lower() else 'К любимому гарниру и хорошему вечеру.'}</p></article>'''
def cards(items):return ''.join(card(p,i+1) for i,p in enumerate(items))

def home_card(p):
 label={'Наггетсы куриные':'Наггетсы','Куриный попкорн':'Попкорн'}.get(p['name'],p['name'])
 return f'''<article class="product-card home-product reveal" data-name="{esc(p['name'].lower())}"><a class="product-image" data-tilt href="{p['url']}" aria-label="{esc(p['name'])}"><img class="tilt-plane" src="{p['image']}" width="600" height="500" loading="lazy" alt="{esc(p['name'])}"></a><a class="product-title" href="{p['url']}"><h3>{esc(label)}</h3><span class="circle-arrow" aria-hidden="true">↗</span></a></article>'''

protein=f'''<section class="protein-section" data-depth-scene id="protein" aria-labelledby="protein-heading">{depth_seam("protein-top", ["meatball"])}<div class="wrap protein-inner"><div class="protein-copy reveal"><p class="eyebrow">02 / в основе — мясо птицы</p><h2 id="protein-heading" class="protein-heading" aria-label="Белок к столу!"><span class="protein-word" aria-hidden="true"><span>БЕЛ</span><span class="protein-o"><img src="assets/protein-letter-art.webp" width="258" height="252" loading="lazy" alt=""></span><span>К</span></span><span class="hand protein-hand" aria-hidden="true">к столу!</span></h2></div><div class="protein-story reveal"><h3>На каждый день.<br>С удовольствием.</h3><p>Курица и индейка — природные источники белка. Он помогает поддерживать мышцы и важен в повседневном рационе.</p><p>А мы делаем из птицы то, что вы любите: фрикадельки, наггетсы и не только.</p>{btn('Выбрать свой вкус','catalogue.html')}</div></div><div class="protein-bridge" aria-hidden="true"><img class="bridge-cluster depth-motion" data-depth="28" data-depth-turn="3" src="assets/meatball-cluster.webp" width="740" height="610" loading="lazy" alt=""><img class="bridge-single depth-motion" data-depth="-24" data-depth-turn="-5" src="assets/meatball-float.webp" width="360" height="360" loading="lazy" alt=""></div></section>'''

home=f'''<section class="hero" data-depth-scene><div class="hero-inner wrap"><div class="hero-copy"><h1>Есть повод<br>собраться.</h1><p>Фрикадельки, наггетсы и другие<br class="desktop-break"> любимые блюда.</p>{btn('Выбрать вкус','catalogue.html','cream')}</div><figure class="hero-art"><img class="depth-motion" data-depth="24" data-depth-turn="1" src="assets/hero-reference.webp" width="768" height="545" fetchpriority="high" alt="Упаковка фрикаделек Новоферма, готовое блюдо и фирменные курочки"></figure></div>{depth_seam("hero", ["meatball"])}</section>
<div class="tagline wrap"><strong>Для ужина. Для кино. Для своих.</strong><span class="tagline-rule"></span>{hand('Больше,<br>чем просто еда')}{heart()}</div>
<section class="section wrap home-products"><div class="section-heading reveal"><div><p class="eyebrow">01 / выбираем любимое</p><h2>У каждого —<br>свой вкус.</h2></div><div class="heading-aside">{hand('Выбирайте сердцем.<br><em>И аппетитом.</em>')}{btn('Весь каталог','catalogue.html')}</div></div><div class="product-grid featured">{''.join(home_card(p) for p in [find('наггетсы куриные'),find('попкорн'),find('стрипсы')])}</div></section>
{protein}
<section class="serving-section"><div class="wrap section"><div class="section-heading reveal"><div><p class="eyebrow">03 / повод найдётся</p><h2>На вечер есть план.</h2></div>{hand('Хорошо сидим! '+heart())}</div><div class="serving-tabs" role="tablist" aria-label="Идеи подачи"><button id="tab-dinner" role="tab" aria-selected="true" aria-controls="serve-panel" tabindex="0" data-serve="dinner"><small>01</small> Для ужина <span aria-hidden="true">→</span></button><button id="tab-movie" role="tab" aria-selected="false" aria-controls="serve-panel" tabindex="-1" data-serve="movie"><small>02</small> Для кино <span aria-hidden="true">→</span></button><button id="tab-company" role="tab" aria-selected="false" aria-controls="serve-panel" tabindex="-1" data-serve="company"><small>03</small> Для компании <span aria-hidden="true">→</span></button></div><div class="serving-content" id="serve-panel" role="tabpanel" aria-labelledby="tab-dinner"><figure><img id="serve-image" src="assets/serving-dinner-crop.webp" width="1008" height="922" loading="lazy" alt="Стрипсы с пюре и овощами — идея подачи"><figcaption class="hand" id="serve-caption">Любимый гарнир уже ждёт</figcaption></figure><div class="serving-copy"><h3 id="serve-heading">Ужин дома.<br>Все свои.</h3><p id="serve-description">Стрипсы, нежное пюре и свежие овощи. Добавьте любимый соус — и зовите к столу.</p>{btn('Выбрать стрипсы',find('стрипсы')['url'],'cream')}</div></div></div></section>
<section class="brand-story" data-depth-scene><div class="wrap brand-inner"><div class="reveal"><p class="eyebrow">04 / это Новоферма</p><h2>Вкусно,<br>когда<br><em>вместе.</em></h2></div><div class="brand-copy reveal"><p>Делаем замороженные продукты из курицы и индейки — для ужинов дома и встреч с друзьями.</p>{hand('На упаковке — наши герои.<br>За столом — ваши.')}{btn('О Новоферме','about.html')}</div><img class="story-mascot" src="assets/mascot-reference.webp" width="400" height="600" loading="lazy" alt=""></div></section>
<section class="section wrap where-preview"><div class="reveal"><p class="eyebrow">05 / осталось попробовать</p><h2>Встретимся<br>на полке.</h2><p>Поможем узнать, где искать<br>Новоферму в вашем городе.</p></div><div class="editorial-links reveal"><a href="where-to-buy.html"><h3>Где купить {arrow()}</h3><p>Уточните точки продаж в вашем городе</p></a><a href="contacts.html"><h3>Задать вопрос {arrow()}</h3><p>О продукте, приготовлении или сотрудничестве</p></a></div></section>{contactband()}'''
page('index.html','Есть повод собраться',home)

catalogue=crumb('Продукция')+f'''<section class="wrap catalogue-page"><div class="page-heading reveal"><div><p class="eyebrow">Продукция Новофермы</p><h1>Что сегодня?</h1></div>{hand('Вкусные идеи<br>на каждый день!')}{heart()}</div><div class="catalogue-tools"><div class="category-filters" role="group" aria-label="Категории"><button data-category-filter="all" aria-pressed="true">Все</button>{''.join(f'<button data-category-filter="{esc(c)}" aria-pressed="false">{c}</button>' for c in dict.fromkeys(p['category'] for p in products))}</div><label class="search"><span aria-hidden="true">⌕</span><input type="search" id="product-search" placeholder="Найти свой вкус" aria-label="Поиск продукта"><button class="search-clear" type="button" aria-label="Очистить поиск" hidden>×</button></label></div><div class="filter-meta"><div class="meat-filters" role="group" aria-label="Вид мяса"><button data-meat-filter="all" aria-pressed="true">Любой</button><button data-meat-filter="chicken" aria-pressed="false">Из курицы</button><button data-meat-filter="turkey" aria-pressed="false">С индейкой</button></div><p id="product-count" role="status" aria-live="polite">{len(products)} продуктов</p></div><div class="product-grid catalogue-grid">{cards(products)}</div><div class="empty-state" hidden><p class="hand">Ничего не нашлось…</p><h2>Попробуем другой вкус?</h2><p>Измените запрос или сбросьте фильтры.</p><button class="button button-dark" id="reset-filters">Показать все продукты {arrow()}</button></div><p class="catalogue-note">Продукция продаётся замороженной. Изображения приготовленных блюд — варианты сервировки.</p></section>{contactband()}'''
page('catalogue.html','Продукция',catalogue,'catalogue.html')

for p in products:
 more=[q for q in products if q['id']!=p['id']][:3]
 details=crumb(f'<a href="catalogue.html">Продукция</a> / {esc(p["name"])}')+f'''<section class="wrap product-detail"><figure class="detail-visual" data-tilt><img class="tilt-plane" src="{p['image']}" width="700" height="650" alt="{esc(p['name'])}"><figcaption>Изображение продукта / вариант сервировки</figcaption></figure><div class="detail-copy reveal"><p class="eyebrow">{p['category']} / {p['meat']}</p><h1>{p['name']}</h1>{hand('К столу и к хорошему настроению.') }<div class="product-facts"><div><span>Масса нетто</span><strong>{p['weight']}</strong></div><div><span>Продукт</span><strong>Замороженный</strong></div></div><p>Знакомый вкус для домашнего ужина, вечера с друзьями и ваших любимых сочетаний.</p><div class="detail-actions">{btn('Где купить','where-to-buy.html?product='+p['id'])}<a class="text-link" href="partners.html">Для партнёров {arrow()}</a></div><div class="product-information"><details open><summary>О продукте <span>+</span></summary><p>{p['name']}. {p['meat']}. Упаковка: контейнер. Масса нетто: {p['weight']}. Храните и готовьте продукт по инструкции на упаковке.</p></details><details><summary>Состав и пищевая ценность <span>+</span></summary><p>Актуальный состав, аллергены и пищевая ценность указаны на этикетке. Чтобы уточнить информацию о продукте, <a href="mailto:info@novoferma.ru?subject={esc(p['name'])}">напишите нам</a>.</p></details><details><summary>Как приготовить и хранить <span>+</span></summary><p>Следуйте способу приготовления, температуре и времени на упаковке конкретного продукта. Если этикетка не сохранилась, уточните инструкцию у нас перед приготовлением.</p></details></div></div></section><section class="related-section"><div class="section wrap"><div class="section-heading reveal"><h2>А ещё к столу…</h2>{btn('Весь каталог','catalogue.html')}</div><div class="product-grid featured">{cards(more)}</div></div></section>'''
 page(p['url'],p['name'],details,'catalogue.html')

about=crumb('О Новоферме')+f'''<section class="about-hero"><div class="wrap split"><div class="reveal"><p class="eyebrow">Это Новоферма</p><h1>Вкусно,<br>когда<br><em>вместе.</em></h1></div><div class="about-intro reveal"><p>Мы производим замороженные полуфабрикаты из курицы и индейки.</p><p>Фрикадельки к любимому гарниру. Наггетсы к хорошему кино. Стрипсы на большую тарелку — чтобы хватило всем.</p>{hand('Повод собраться<br>найдётся всегда.')}</div></div></section><section class="wrap section about-editorial" data-depth-scene><figure class="reveal editorial-photo"><img src="assets/serving-company-crop.webp" width="1008" height="922" alt="Идея подачи: общая тарелка закусок" loading="lazy"><figcaption class="hand">Место для своих</figcaption></figure><div class="reveal"><p class="eyebrow">От Новофермы — к вашему столу</p><h2>Любимые блюда.<br>Ваши истории.</h2><p>В нашей линейке — котлеты и биточки, фрикадельки, наггетсы, куриный попкорн и стрипсы. Выбирайте то, что хочется приготовить сегодня.</p><p>За информацией о составе и приготовлении обращайтесь к упаковке продукта. Если остались вопросы — мы на связи.</p>{btn('Смотреть продукты','catalogue.html') }</div></section><section class="brand-story" data-depth-scene>{depth_seam("about", ["nugget"])}<div class="wrap brand-inner"><div><p class="eyebrow">Наши герои</p><h2>С&nbsp;характером.<br>И&nbsp;аппетитом.</h2></div><div class="brand-copy"><p>Курочки на упаковке — часть мира Новофермы. Немного юмора и домашнего тепла рядом с любимыми вкусами.</p>{hand('На упаковке — наши герои.<br>За столом — ваши.')}</div><img class="story-mascot" src="assets/mascot-reference.webp" width="400" height="600" loading="lazy" alt=""></div></section>{contactband()}'''
