where=crumb('Где купить')+f'''<section class="wrap section page-intro"><p class="eyebrow">Рядом с вами</p><div class="section-heading"><h1>Встретимся<br>на полке.</h1>{hand('Осталось<br>попробовать! '+heart())}</div><p class="lead">Подскажем, где искать Новоферму<br>в вашем городе.</p></section><section class="wrap where-layout"><div class="city-panel" data-depth-scene>{depth_seam("shop", ["nugget"])}<p class="eyebrow">Уточнить точки продаж</p><h2>В каком<br>вы городе?</h2><form id="city-form"><label for="city">Город</label><input id="city" name="city" autocomplete="address-level2" placeholder="Например, Санкт-Петербург" required maxlength="100"><label for="wanted-product">Что хотите найти?</label><select id="wanted-product" name="product"><option value="">Весь ассортимент</option>{''.join(f'<option value="{p["id"]}">{esc(p["name"])}</option>' for p in products)}</select><button class="button button-dark" type="submit">Составить письмо {arrow()}</button><p class="form-hint">Откроется ваша почта с готовым вопросом.<br>Письмо отправляете вы.</p></form><p class="form-feedback" role="status" hidden></p></div><div class="where-explanation reveal">{hand('Ваш любимый вкус<br>где-то рядом.') }<h3>Поможем с поиском</h3><p>Перечень магазинов сейчас уточняется. Напишите город и интересующий продукт — так нам будет проще подсказать точку продажи.</p><a class="large-link" href="mailto:info@novoferma.ru">info@novoferma.ru {arrow()}</a><p>Можно также позвонить в офис:</p><a class="phone-link" href="tel:+78129155454">+7 (812) 915-54-54</a><div class="small-note">Наличие и ассортимент зависят от магазина. Уточните их у продавца перед поездкой.</div></div></section>'''
